package com.dsavisualizer.app.data.provider;

import com.dsavisualizer.app.model.CategoryItem;
import com.dsavisualizer.app.model.TechniqueContent;
import com.dsavisualizer.app.model.TechniqueItem;

import java.util.List;
import java.util.Map;

/**
 * Curated provider for String and Pattern Matching algorithms.
 * Includes complete Iterative, Functions, and Recursion algorithms and code (Java, C, Python).
 */
public final class StringPatternProvider {

    private StringPatternProvider() {}

    public static void register(
        List<CategoryItem> categories,
        List<TechniqueItem> techniques,
        Map<String, TechniqueContent> contentMap
    ) {
        categories.add(new CategoryItem(
            "string_pattern",
            "String & Pattern Matching",
            "Fast substring search, failure functions, tries, and text processing",
            "#06B6D4"
        ));

        // 1. KMP
        techniques.add(new TechniqueItem(
            "string_kmp",
            "string_pattern",
            "Knuth-Morris-Pratt (KMP)",
            "Prefix-function LPS array skips redundant text re-scans • O(n+m)",
            "Medium"
        ));
        // 2. Rabin-Karp
        techniques.add(new TechniqueItem(
            "string_rabin_karp",
            "string_pattern",
            "Rabin-Karp Algorithm",
            "Polynomial rolling hash window matching • O(n+m)",
            "Medium"
        ));
        // 3. Boyer-Moore
        techniques.add(new TechniqueItem(
            "string_boyer_moore",
            "string_pattern",
            "Boyer-Moore Algorithm",
            "Right-to-left scan with Bad Character & Good Suffix heuristics",
            "Hard"
        ));
        // 4. Z-Algorithm
        techniques.add(new TechniqueItem(
            "string_z_algorithm",
            "string_pattern",
            "Z-Algorithm",
            "Linear time longest prefix match lengths via [L, R] Z-boxes",
            "Medium"
        ));
        // 5. Aho-Corasick
        techniques.add(new TechniqueItem(
            "string_aho_corasick",
            "string_pattern",
            "Aho-Corasick Algorithm",
            "Trie with failure transitions for simultaneous multi-pattern search",
            "Hard"
        ));
        // 6. Suffix Array & LCP Array
        techniques.add(new TechniqueItem(
            "string_suffix_array",
            "string_pattern",
            "Suffix Array & LCP Array",
            "Sorted lexicographical suffixes enabling fast full-text substring queries",
            "Hard"
        ));
        // 7. Manacher's Algorithm
        techniques.add(new TechniqueItem(
            "string_manacher",
            "string_pattern",
            "Manacher's Algorithm",
            "Find longest palindromic substring in strictly linear O(n) time",
            "Hard"
        ));

        registerKmp(contentMap);
        registerRabinKarp(contentMap);
        registerBoyerMoore(contentMap);
        registerZAlgorithm(contentMap);
        registerAhoCorasick(contentMap);
        registerSuffixArray(contentMap);
        registerManacher(contentMap);
    }

    private static void registerKmp(Map<String, TechniqueContent> contentMap) {
        TechniqueContent tc = new TechniqueContent(
            "string_kmp",
            "Knuth-Morris-Pratt (KMP) Algorithm",
            "Searches for occurrences of a pattern P within text T in O(N + M) time.\n\nIt uses a precomputed Longest Prefix which is also Suffix (LPS) array. When a mismatch occurs after some matches, LPS tells us the next character in pattern to compare without backing up the text pointer.",
            "Ctrl+F text search inside code editors and document processors without backtracking.",
            "O(N + M)", "O(N + M)", "O(N + M)", "O(M)",
            new int[] {65, 66, 65, 66, 67},
            5
        );

        tc.algorithmByStyle.put("Iterative", "Algorithm: KMP_ITERATIVE(txt, pat)\n1. Compute LPS array of size M = len(pat).\n2. Set i = 0 (text pointer) and j = 0 (pattern pointer).\n3. While i < N (len(txt)):\n   If pat[j] == txt[i]:\n     i++, j++\n   If j == M:\n     Record match at index (i - j)\n     j = lps[j - 1]\n   Else if i < N and pat[j] != txt[i]:\n     If j != 0: j = lps[j - 1]\n     Else: i++.");
        tc.algorithmByStyle.put("Functions", "Algorithm: KMP_FUNCTIONAL(txt, pat)\nFUNCTION COMPUTE_LPS(pat, M):\n  Build lps table tracking longest prefix also suffix for pat[0..i].\n\nFUNCTION KMP_SEARCH(txt, pat):\n  Call COMPUTE_LPS(pat).\n  Scan text iteratively stepping pattern index using lps.\n  Return list of matched indices.");
        tc.algorithmByStyle.put("Recursion", "Algorithm: KMP_RECURSIVE(txt, pat, i, j, lps, matches)\n1. If i >= len(txt): return matches.\n2. If pat[j] == txt[i]:\n     If j + 1 == len(pat):\n       matches.add(i - j)\n       return KMP_RECURSIVE(txt, pat, i + 1, lps[j], lps, matches)\n     Else:\n       return KMP_RECURSIVE(txt, pat, i + 1, j + 1, lps, matches)\n3. Else (mismatch):\n     If j > 0:\n       return KMP_RECURSIVE(txt, pat, i, lps[j - 1], lps, matches)\n     Else:\n       return KMP_RECURSIVE(txt, pat, i + 1, 0, lps, matches)");

        tc.putCode("Java", "Iterative", "// KMP Algorithm - Iterative Search\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class KmpIterative {\n    public static List<Integer> searchKMP(String pat, String txt) {\n        List<Integer> result = new ArrayList<>();\n        int M = pat.length(), N = txt.length();\n        int[] lps = computeLPS(pat);\n        int i = 0, j = 0;\n\n        while (i < N) {\n            if (pat.charAt(j) == txt.charAt(i)) {\n                i++;\n                j++;\n            }\n            if (j == M) {\n                result.add(i - j);\n                j = lps[j - 1];\n            } else if (i < N && pat.charAt(j) != txt.charAt(i)) {\n                if (j != 0) j = lps[j - 1];\n                else i++;\n            }\n        }\n        return result;\n    }\n\n    private static int[] computeLPS(String pat) {\n        int m = pat.length();\n        int[] lps = new int[m];\n        int len = 0, i = 1;\n        while (i < m) {\n            if (pat.charAt(i) == pat.charAt(len)) {\n                len++;\n                lps[i] = len;\n                i++;\n            } else {\n                if (len != 0) len = lps[len - 1];\n                else { lps[i] = 0; i++; }\n            }\n        }\n        return lps;\n    }\n}", true);
        tc.putCode("Java", "Functions", "// KMP Algorithm - Functional Modular\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class KmpFunctional {\n    public static int[] getLpsTable(String pattern) {\n        int[] lps = new int[pattern.length()];\n        int len = 0, i = 1;\n        while (i < pattern.length()) {\n            if (pattern.charAt(i) == pattern.charAt(len)) {\n                lps[i++] = ++len;\n            } else if (len > 0) {\n                len = lps[len - 1];\n            } else {\n                lps[i++] = 0;\n            }\n        }\n        return lps;\n    }\n\n    public static List<Integer> findMatches(String txt, String pat) {\n        List<Integer> indices = new ArrayList<>();\n        int[] lps = getLpsTable(pat);\n        int i = 0, j = 0;\n        while (i < txt.length()) {\n            if (txt.charAt(i) == pat.charAt(j)) {\n                i++; j++;\n            }\n            if (j == pat.length()) {\n                indices.add(i - j);\n                j = lps[j - 1];\n            } else if (i < txt.length() && txt.charAt(i) != pat.charAt(j)) {\n                j = (j > 0) ? lps[j - 1] : 0;\n                if (j == 0 && txt.charAt(i) != pat.charAt(0)) i++;\n            }\n        }\n        return indices;\n    }\n}", true);
        tc.putCode("Java", "Recursion", "// KMP Algorithm - Recursive Pattern Matching\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class KmpRecursive {\n    public static List<Integer> search(String txt, String pat) {\n        int[] lps = computeLps(pat);\n        List<Integer> matches = new ArrayList<>();\n        searchRec(txt, pat, 0, 0, lps, matches);\n        return matches;\n    }\n\n    private static void searchRec(String txt, String pat, int i, int j, int[] lps, List<Integer> matches) {\n        if (i >= txt.length()) return;\n\n        if (pat.charAt(j) == txt.charAt(i)) {\n            if (j + 1 == pat.length()) {\n                matches.add(i - j);\n                searchRec(txt, pat, i + 1, lps[j], lps, matches);\n            } else {\n                searchRec(txt, pat, i + 1, j + 1, lps, matches);\n            }\n        } else {\n            if (j > 0) {\n                searchRec(txt, pat, i, lps[j - 1], lps, matches);\n            } else {\n                searchRec(txt, pat, i + 1, 0, lps, matches);\n            }\n        }\n    }\n\n    private static int[] computeLps(String pat) {\n        int[] lps = new int[pat.length()];\n        int len = 0, i = 1;\n        while (i < pat.length()) {\n            if (pat.charAt(i) == pat.charAt(len)) lps[i++] = ++len;\n            else if (len > 0) len = lps[len - 1];\n            else lps[i++] = 0;\n        }\n        return lps;\n    }\n}", true);

        tc.putCode("C", "Iterative", "/* KMP Algorithm - Iterative Search (C) */\n#include <stdio.h>\n#include <string.h>\n\nvoid computeLPS(const char* pat, int M, int* lps) {\n    int len = 0, i = 1;\n    lps[0] = 0;\n    while (i < M) {\n        if (pat[i] == pat[len]) {\n            len++;\n            lps[i++] = len;\n        } else {\n            if (len != 0) len = lps[len - 1];\n            else lps[i++] = 0;\n        }\n    }\n}\n\nvoid searchKMP(const char* pat, const char* txt) {\n    int M = strlen(pat), N = strlen(txt);\n    int lps[M];\n    computeLPS(pat, M, lps);\n    int i = 0, j = 0;\n\n    while (i < N) {\n        if (pat[j] == txt[i]) { i++; j++; }\n        if (j == M) {\n            printf(\"Found pattern at index %d\\n\", i - j);\n            j = lps[j - 1];\n        } else if (i < N && pat[j] != txt[i]) {\n            if (j != 0) j = lps[j - 1];\n            else i++;\n        }\n    }\n}", true);
        tc.putCode("C", "Functions", "/* KMP Algorithm - Functional Modular (C) */\n#include <stdio.h>\n#include <string.h>\n\nvoid buildLpsArray(const char* p, int m, int lps[]) {\n    int k = 0;\n    lps[0] = 0;\n    for (int i = 1; i < m; i++) {\n        while (k > 0 && p[k] != p[i]) k = lps[k - 1];\n        if (p[k] == p[i]) k++;\n        lps[i] = k;\n    }\n}\n\nint matchKmpModular(const char* t, const char* p) {\n    int n = strlen(t), m = strlen(p);\n    int lps[m];\n    buildLpsArray(p, m, lps);\n    int q = 0;\n    for (int i = 0; i < n; i++) {\n        while (q > 0 && p[q] != t[i]) q = lps[q - 1];\n        if (p[q] == t[i]) q++;\n        if (q == m) {\n            return i - m + 1; // Return first match\n        }\n    }\n    return -1;\n}", true);
        tc.putCode("C", "Recursion", "/* KMP Algorithm - Recursive (C) */\n#include <stdio.h>\n#include <string.h>\n\nvoid kmpRec(const char* txt, const char* pat, int i, int j, const int lps[], int n, int m) {\n    if (i >= n) return;\n\n    if (pat[j] == txt[i]) {\n        if (j + 1 == m) {\n            printf(\"Match at index %d\\n\", i - j);\n            kmpRec(txt, pat, i + 1, lps[j], lps, n, m);\n        } else {\n            kmpRec(txt, pat, i + 1, j + 1, lps, n, m);\n        }\n    } else {\n        if (j > 0) kmpRec(txt, pat, i, lps[j - 1], lps, n, m);\n        else kmpRec(txt, pat, i + 1, 0, lps, n, m);\n    }\n}", true);

        tc.putCode("Python", "Iterative", "# KMP Algorithm - Iterative Search (Python)\ndef kmp_search_iterative(txt: str, pat: str) -> list[int]:\n    n, m = len(txt), len(pat)\n    if m == 0: return []\n\n    # Compute LPS\n    lps = [0] * m\n    length, i = 0, 1\n    while i < m:\n        if pat[i] == pat[length]:\n            length += 1\n            lps[i] = length\n            i += 1\n        elif length > 0:\n            length = lps[length - 1]\n        else:\n            lps[i] = 0\n            i += 1\n\n    # Search\n    matches = []\n    i = j = 0\n    while i < n:\n        if pat[j] == txt[i]:\n            i += 1\n            j += 1\n        if j == m:\n            matches.append(i - j)\n            j = lps[j - 1]\n        elif i < n and pat[j] != txt[i]:\n            j = lps[j - 1] if j > 0 else 0\n            if j == 0 and pat[0] != txt[i]:\n                i += 1\n\n    return matches\n", true);
        tc.putCode("Python", "Functions", "# KMP Algorithm - Functional Modular (Python)\ndef compute_lps(pattern: str) -> list[int]:\n    lps = [0] * len(pattern)\n    k = 0\n    for i in range(1, len(pattern)):\n        while k > 0 and pattern[k] != pattern[i]:\n            k = lps[k - 1]\n        if pattern[k] == pattern[i]:\n            k += 1\n        lps[i] = k\n    return lps\n\ndef kmp_search_functional(text: str, pattern: str) -> list[int]:\n    lps = compute_lps(pattern)\n    matches = []\n    q = 0\n    for i, ch in enumerate(text):\n        while q > 0 and pattern[q] != ch:\n            q = lps[q - 1]\n        if pattern[q] == ch:\n            q += 1\n        if q == len(pattern):\n            matches.append(i - len(pattern) + 1)\n            q = lps[q - 1]\n    return matches\n", true);
        tc.putCode("Python", "Recursion", "# KMP Algorithm - Recursive (Python)\ndef kmp_search_recursive(txt: str, pat: str) -> list[int]:\n    def get_lps(p: str) -> list[int]:\n        lps = [0] * len(p)\n        k = 0\n        for i in range(1, len(p)):\n            while k > 0 and p[k] != p[i]: k = lps[k - 1]\n            if p[k] == p[i]: k += 1\n            lps[i] = k\n        return lps\n\n    lps = get_lps(pat)\n    matches = []\n\n    def scan(i: int, j: int):\n        if i >= len(txt): return\n        if pat[j] == txt[i]:\n            if j + 1 == len(pat):\n                matches.append(i - j)\n                scan(i + 1, lps[j])\n            else:\n                scan(i + 1, j + 1)\n        else:\n            if j > 0: scan(i, lps[j - 1])\n            else: scan(i + 1, 0)\n\n    scan(0, 0)\n    return matches\n", true);

        contentMap.put(tc.techniqueId, tc);
    }

    private static void registerRabinKarp(Map<String, TechniqueContent> contentMap) {
        TechniqueContent tc = new TechniqueContent(
            "string_rabin_karp",
            "Rabin-Karp Algorithm",
            "Matches pattern against text using a rolling hash function.\n\nComputes the hash of the pattern and the hash of the first window of text. If hashes match, it performs character-by-character check to eliminate hash collisions. Slides the window in O(1) by subtracting the leading char and adding the trailing char.",
            "Plagiarism detection scanners comparing student essays across large online corpora.",
            "O(N + M)", "O(N + M)", "O(N * M)", "O(1)",
            new int[] {65, 66, 65, 66, 65},
            3
        );

        tc.algorithmByStyle.put("Iterative", "Algorithm: RABIN_KARP_ITERATIVE(txt, pat, prime, base)\n1. Compute pat_hash and initial txt_window_hash.\n2. For s from 0 to N - M:\n     If pat_hash == txt_window_hash:\n       If txt[s..s+M-1] == pat:\n         Record match at index s.\n     If s < N - M:\n       Roll hash: subtract txt[s], multiply base, add txt[s+M] (mod prime).\n3. Return matches.");
        tc.algorithmByStyle.put("Functions", "Algorithm: RABIN_KARP_FUNCTIONAL(txt, pat)\nFUNCTION HASH_WINDOW(str, len, base, mod):\n  Compute polynomial hash.\nFUNCTION ROLL_HASH(old_hash, old_char, new_char, h, base, mod):\n  Update hash in O(1).\nFUNCTION SEARCH(txt, pat):\n  Slide window using ROLL_HASH, verifying on collision.");
        tc.algorithmByStyle.put("Recursion", "Algorithm: RABIN_KARP_RECURSIVE(txt, pat, idx, pat_hash, win_hash, h, base, mod, matches)\n1. If idx > N - M: return matches.\n2. If pat_hash == win_hash and txt[idx..idx+M-1] == pat:\n     matches.add(idx)\n3. If idx < N - M:\n     new_win_hash = ROLL_HASH(win_hash, txt[idx], txt[idx+M])\n     return RABIN_KARP_RECURSIVE(txt, pat, idx + 1, pat_hash, new_win_hash, ...)");

        tc.putCode("Java", "Iterative", "// Rabin-Karp Algorithm - Iterative Sliding Window\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class RabinKarpIterative {\n    public static List<Integer> search(String pat, String txt, int q) {\n        List<Integer> matches = new ArrayList<>();\n        int d = 256;\n        int M = pat.length(), N = txt.length();\n        int p = 0, t = 0, h = 1;\n\n        for (int i = 0; i < M - 1; i++) h = (h * d) % q;\n\n        for (int i = 0; i < M; i++) {\n            p = (d * p + pat.charAt(i)) % q;\n            t = (d * t + txt.charAt(i)) % q;\n        }\n\n        for (int i = 0; i <= N - M; i++) {\n            if (p == t) {\n                boolean match = true;\n                for (int j = 0; j < M; j++) {\n                    if (txt.charAt(i + j) != pat.charAt(j)) { match = false; break; }\n                }\n                if (match) matches.add(i);\n            }\n            if (i < N - M) {\n                t = (d * (t - txt.charAt(i) * h) + txt.charAt(i + M)) % q;\n                if (t < 0) t += q;\n            }\n        }\n        return matches;\n    }\n}", true);
        tc.putCode("Java", "Functions", "// Rabin-Karp Algorithm - Functional Modular\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class RabinKarpFunctional {\n    private static final int BASE = 256;\n    private static final int MOD = 101;\n\n    private static int rollHash(int currentHash, char oldChar, char newChar, int h) {\n        int next = (BASE * (currentHash - oldChar * h) + newChar) % MOD;\n        return (next < 0) ? next + MOD : next;\n    }\n\n    public static List<Integer> search(String txt, String pat) {\n        List<Integer> result = new ArrayList<>();\n        int m = pat.length(), n = txt.length();\n        int h = 1, pHash = 0, tHash = 0;\n\n        for (int i = 0; i < m - 1; i++) h = (h * BASE) % MOD;\n        for (int i = 0; i < m; i++) {\n            pHash = (BASE * pHash + pat.charAt(i)) % MOD;\n            tHash = (BASE * tHash + txt.charAt(i)) % MOD;\n        }\n\n        for (int i = 0; i <= n - m; i++) {\n            if (pHash == tHash && txt.substring(i, i + m).equals(pat)) {\n                result.add(i);\n            }\n            if (i < n - m) {\n                tHash = rollHash(tHash, txt.charAt(i), txt.charAt(i + m), h);\n            }\n        }\n        return result;\n    }\n}", true);
        tc.putCode("Java", "Recursion", "// Rabin-Karp Algorithm - Recursive Search\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class RabinKarpRecursive {\n    private static final int BASE = 256;\n    private static final int MOD = 101;\n\n    public static List<Integer> search(String txt, String pat) {\n        List<Integer> matches = new ArrayList<>();\n        int m = pat.length(), n = txt.length();\n        if (n < m) return matches;\n\n        int h = 1, pHash = 0, tHash = 0;\n        for (int i = 0; i < m - 1; i++) h = (h * BASE) % MOD;\n        for (int i = 0; i < m; i++) {\n            pHash = (BASE * pHash + pat.charAt(i)) % MOD;\n            tHash = (BASE * tHash + txt.charAt(i)) % MOD;\n        }\n\n        stepRec(txt, pat, 0, pHash, tHash, h, matches);\n        return matches;\n    }\n\n    private static void stepRec(String txt, String pat, int i, int pHash, int tHash, int h, List<Integer> matches) {\n        int m = pat.length(), n = txt.length();\n        if (i > n - m) return;\n\n        if (pHash == tHash && txt.startsWith(pat, i)) {\n            matches.add(i);\n        }\n        if (i < n - m) {\n            int nextHash = (BASE * (tHash - txt.charAt(i) * h) + txt.charAt(i + m)) % MOD;\n            if (nextHash < 0) nextHash += MOD;\n            stepRec(txt, pat, i + 1, pHash, nextHash, h, matches);\n        }\n    }\n}", true);

        tc.putCode("C", "Iterative", "/* Rabin-Karp Algorithm - Iterative (C) */\n#include <stdio.h>\n#include <string.h>\n\n#define D 256\n\nvoid searchRabinKarp(const char* pat, const char* txt, int q) {\n    int M = strlen(pat), N = strlen(txt);\n    int p = 0, t = 0, h = 1;\n\n    for (int i = 0; i < M - 1; i++) h = (h * D) % q;\n    for (int i = 0; i < M; i++) {\n        p = (D * p + pat[i]) % q;\n        t = (D * t + txt[i]) % q;\n    }\n\n    for (int i = 0; i <= N - M; i++) {\n        if (p == t) {\n            int j;\n            for (j = 0; j < M; j++) if (txt[i + j] != pat[j]) break;\n            if (j == M) printf(\"Pattern found at index %d\\n\", i);\n        }\n        if (i < N - M) {\n            t = (D * (t - txt[i] * h) + txt[i + M]) % q;\n            if (t < 0) t += q;\n        }\n    }\n}", true);
        tc.putCode("C", "Functions", "/* Rabin-Karp Algorithm - Functional (C) */\n#include <stdio.h>\n#include <string.h>\n\n#define D 256\n#define Q 101\n\nint roll(int hash, char oldChar, char newChar, int h) {\n    int res = (D * (hash - oldChar * h) + newChar) % Q;\n    return (res < 0) ? res + Q : res;\n}\n\nvoid rabinKarpFunctional(const char* pat, const char* txt) {\n    int m = strlen(pat), n = strlen(txt);\n    int p = 0, t = 0, h = 1;\n    for (int i = 0; i < m - 1; i++) h = (h * D) % Q;\n    for (int i = 0; i < m; i++) {\n        p = (D * p + pat[i]) % Q;\n        t = (D * t + txt[i]) % Q;\n    }\n\n    for (int i = 0; i <= n - m; i++) {\n        if (p == t && strncmp(txt + i, pat, m) == 0) {\n            printf(\"Found at %d\\n\", i);\n        }\n        if (i < n - m) t = roll(t, txt[i], txt[i + m], h);\n    }\n}", true);
        tc.putCode("C", "Recursion", "/* Rabin-Karp Algorithm - Recursive (C) */\n#include <stdio.h>\n#include <string.h>\n\n#define D 256\n#define Q 101\n\nvoid rkRec(const char* txt, const char* pat, int i, int p, int t, int h, int m, int n) {\n    if (i > n - m) return;\n    if (p == t && strncmp(txt + i, pat, m) == 0) {\n        printf(\"Match at %d\\n\", i);\n    }\n    if (i < n - m) {\n        int next = (D * (t - txt[i] * h) + txt[i + m]) % Q;\n        if (next < 0) next += Q;\n        rkRec(txt, pat, i + 1, p, next, h, m, n);\n    }\n}", true);

        tc.putCode("Python", "Iterative", "# Rabin-Karp Algorithm - Iterative (Python)\ndef rabin_karp_iterative(txt: str, pat: str, q: int = 101) -> list[int]:\n    d = 256\n    m, n = len(pat), len(txt)\n    if m == 0 or n < m: return []\n\n    p = t = 0\n    h = pow(d, m - 1, q)\n    matches = []\n\n    for i in range(m):\n        p = (d * p + ord(pat[i])) % q\n        t = (d * t + ord(txt[i])) % q\n\n    for i in range(n - m + 1):\n        if p == t and txt[i:i + m] == pat:\n            matches.append(i)\n        if i < n - m:\n            t = (d * (t - ord(txt[i]) * h) + ord(txt[i + m])) % q\n            if t < 0: t += q\n\n    return matches\n", true);
        tc.putCode("Python", "Functions", "# Rabin-Karp Algorithm - Functional (Python)\ndef rabin_karp_functional(txt: str, pat: str, q: int = 101) -> list[int]:\n    d = 256\n    m, n = len(pat), len(txt)\n\n    def roll(curr_hash: int, old_c: str, new_c: str, h: int) -> int:\n        h_val = (d * (curr_hash - ord(old_c) * h) + ord(new_c)) % q\n        return h_val + q if h_val < 0 else h_val\n\n    h = pow(d, m - 1, q)\n    p = sum(ord(pat[i]) * pow(d, m - 1 - i, q) for i in range(m)) % q\n    t = sum(ord(txt[i]) * pow(d, m - 1 - i, q) for i in range(m)) % q\n\n    matches = []\n    for i in range(n - m + 1):\n        if p == t and txt[i:i + m] == pat:\n            matches.append(i)\n        if i < n - m:\n            t = roll(t, txt[i], txt[i + m], h)\n    return matches\n", true);
        tc.putCode("Python", "Recursion", "# Rabin-Karp Algorithm - Recursive (Python)\ndef rabin_karp_recursive(txt: str, pat: str, q: int = 101) -> list[int]:\n    d = 256\n    m, n = len(pat), len(txt)\n    if n < m: return []\n\n    h = pow(d, m - 1, q)\n    p = sum(ord(pat[i]) * pow(d, m - 1 - i, q) for i in range(m)) % q\n    t = sum(ord(txt[i]) * pow(d, m - 1 - i, q) for i in range(m)) % q\n    matches = []\n\n    def scan(i: int, current_hash: int):\n        if i > n - m: return\n        if p == current_hash and txt[i:i + m] == pat:\n            matches.append(i)\n        if i < n - m:\n            nxt = (d * (current_hash - ord(txt[i]) * h) + ord(txt[i + m])) % q\n            if nxt < 0: nxt += q\n            scan(i + 1, nxt)\n\n    scan(0, t)\n    return matches\n", true);

        contentMap.put(tc.techniqueId, tc);
    }

    private static void registerBoyerMoore(Map<String, TechniqueContent> contentMap) {
        TechniqueContent tc = new TechniqueContent(
            "string_boyer_moore",
            "Boyer-Moore Algorithm",
            "Right-to-left scan with Bad Character & Good Suffix heuristics.\n\nPreprocesses pattern to determine shift distances when a mismatch occurs, allowing substantial skips across the text in sub-linear average time.",
            "Fast grep and search-and-replace command-line utilities.",
            "O(N / M)", "O(N)", "O(N * M)", "O(Alphabet)",
            new int[] {66, 65, 78, 65, 78, 65},
            4
        );

        tc.algorithmByStyle.put("Iterative", "Algorithm: BOYER_MOORE_ITERATIVE(txt, pat)\n1. Construct bad character shift table badChar[256] initialized to -1.\n2. For each index i in pat: badChar[pat[i]] = i.\n3. Set s = 0 (shift of pattern with respect to text).\n4. While s <= N - M:\n     Set j = M - 1.\n     While j >= 0 and pat[j] == txt[s + j]: j--\n     If j < 0:\n       Record match at shift s.\n       s += (s + M < N) ? M - badChar[txt[s + M]] : 1\n     Else:\n       s += max(1, j - badChar[txt[s + j]])");
        tc.algorithmByStyle.put("Functions", "Algorithm: BOYER_MOORE_FUNCTIONAL(txt, pat)\nFUNCTION BUILD_BAD_CHAR(pat, m):\n  Map each ASCII character to its rightmost occurrence index.\nFUNCTION SEARCH_BM(txt, pat):\n  Repeatedly evaluate rightmost character alignment and skip using badChar table.");
        tc.algorithmByStyle.put("Recursion", "Algorithm: BOYER_MOORE_RECURSIVE(txt, pat, s, badChar, matches)\n1. If s > N - M: return matches.\n2. Scan right-to-left from j = M - 1 down to 0.\n3. If all match: matches.add(s), step = (s + M < N) ? M - badChar[txt[s + M]] : 1.\n4. Else step = max(1, j - badChar[txt[s + j]]).\n5. Return BOYER_MOORE_RECURSIVE(txt, pat, s + step, badChar, matches).");

        tc.putCode("Java", "Iterative", "// Boyer-Moore - Iterative (Bad Character Heuristic)\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class BoyerMooreIterative {\n    private static final int NO_OF_CHARS = 256;\n\n    public static List<Integer> search(String txt, String pat) {\n        List<Integer> matches = new ArrayList<>();\n        int m = pat.length(), n = txt.length();\n        int[] badChar = new int[NO_OF_CHARS];\n        java.util.Arrays.fill(badChar, -1);\n        for (int i = 0; i < m; i++) badChar[pat.charAt(i)] = i;\n\n        int s = 0;\n        while (s <= (n - m)) {\n            int j = m - 1;\n            while (j >= 0 && pat.charAt(j) == txt.charAt(s + j)) j--;\n\n            if (j < 0) {\n                matches.add(s);\n                s += (s + m < n) ? m - badChar[txt.charAt(s + m)] : 1;\n            } else {\n                s += Math.max(1, j - badChar[txt.charAt(s + j)]);\n            }\n        }\n        return matches;\n    }\n}", true);
        tc.putCode("Java", "Functions", "// Boyer-Moore - Functional Modular\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class BoyerMooreFunctional {\n    private static int[] makeBadCharTable(String pat) {\n        int[] table = new int[256];\n        java.util.Arrays.fill(table, -1);\n        for (int i = 0; i < pat.length(); i++) table[pat.charAt(i)] = i;\n        return table;\n    }\n\n    public static List<Integer> search(String txt, String pat) {\n        List<Integer> matches = new ArrayList<>();\n        int[] badChar = makeBadCharTable(pat);\n        int m = pat.length(), n = txt.length();\n        int s = 0;\n\n        while (s <= n - m) {\n            int j = m - 1;\n            while (j >= 0 && pat.charAt(j) == txt.charAt(s + j)) j--;\n            if (j < 0) {\n                matches.add(s);\n                s += (s + m < n) ? m - badChar[txt.charAt(s + m)] : 1;\n            } else {\n                s += Math.max(1, j - badChar[txt.charAt(s + j)]);\n            }\n        }\n        return matches;\n    }\n}", true);
        tc.putCode("Java", "Recursion", "// Boyer-Moore - Recursive Search\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class BoyerMooreRecursive {\n    public static List<Integer> search(String txt, String pat) {\n        int[] badChar = new int[256];\n        java.util.Arrays.fill(badChar, -1);\n        for (int i = 0; i < pat.length(); i++) badChar[pat.charAt(i)] = i;\n\n        List<Integer> matches = new ArrayList<>();\n        stepRec(txt, pat, 0, badChar, matches);\n        return matches;\n    }\n\n    private static void stepRec(String txt, String pat, int s, int[] badChar, List<Integer> matches) {\n        int m = pat.length(), n = txt.length();\n        if (s > n - m) return;\n\n        int j = m - 1;\n        while (j >= 0 && pat.charAt(j) == txt.charAt(s + j)) j--;\n\n        int nextShift;\n        if (j < 0) {\n            matches.add(s);\n            nextShift = (s + m < n) ? m - badChar[txt.charAt(s + m)] : 1;\n        } else {\n            nextShift = Math.max(1, j - badChar[txt.charAt(s + j)]);\n        }\n        stepRec(txt, pat, s + nextShift, badChar, matches);\n    }\n}", true);

        tc.putCode("C", "Iterative", "/* Boyer-Moore Algorithm - Iterative (C) */\n#include <stdio.h>\n#include <string.h>\n\n#define MAX_CHARS 256\nint max(int a, int b) { return (a > b) ? a : b; }\n\nvoid searchBoyerMoore(const char* txt, const char* pat) {\n    int m = strlen(pat), n = strlen(txt);\n    int badChar[MAX_CHARS];\n    for (int i = 0; i < MAX_CHARS; i++) badChar[i] = -1;\n    for (int i = 0; i < m; i++) badChar[(unsigned char)pat[i]] = i;\n\n    int s = 0;\n    while (s <= n - m) {\n        int j = m - 1;\n        while (j >= 0 && pat[j] == txt[s + j]) j--;\n        if (j < 0) {\n            printf(\"Pattern occurs at shift = %d\\n\", s);\n            s += (s + m < n) ? m - badChar[(unsigned char)txt[s + m]] : 1;\n        } else {\n            s += max(1, j - badChar[(unsigned char)txt[s + j]]);\n        }\n    }\n}", true);
        tc.putCode("C", "Functions", "/* Boyer-Moore Algorithm - Functional (C) */\n#include <stdio.h>\n#include <string.h>\n\nint maxVal(int a, int b) { return (a > b) ? a : b; }\n\nvoid initBadChar(const char* pat, int m, int badChar[256]) {\n    for (int i = 0; i < 256; i++) badChar[i] = -1;\n    for (int i = 0; i < m; i++) badChar[(unsigned char)pat[i]] = i;\n}\n\nvoid bmSearchFunctional(const char* txt, const char* pat) {\n    int m = strlen(pat), n = strlen(txt);\n    int badChar[256];\n    initBadChar(pat, m, badChar);\n    int s = 0;\n\n    while (s <= n - m) {\n        int j = m - 1;\n        while (j >= 0 && pat[j] == txt[s + j]) j--;\n        if (j < 0) {\n            printf(\"Match at %d\\n\", s);\n            s += (s + m < n) ? m - badChar[(unsigned char)txt[s + m]] : 1;\n        } else {\n            s += maxVal(1, j - badChar[(unsigned char)txt[s + j]]);\n        }\n    }\n}", true);
        tc.putCode("C", "Recursion", "/* Boyer-Moore Algorithm - Recursive (C) */\n#include <stdio.h>\n#include <string.h>\n\nint maxVal(int a, int b) { return (a > b) ? a : b; }\n\nvoid bmRec(const char* txt, const char* pat, int s, const int badChar[256], int m, int n) {\n    if (s > n - m) return;\n    int j = m - 1;\n    while (j >= 0 && pat[j] == txt[s + j]) j--;\n\n    int nextShift;\n    if (j < 0) {\n        printf(\"Match at %d\\n\", s);\n        nextShift = (s + m < n) ? m - badChar[(unsigned char)txt[s + m]] : 1;\n    } else {\n        nextShift = maxVal(1, j - badChar[(unsigned char)txt[s + j]]);\n    }\n    bmRec(txt, pat, s + nextShift, badChar, m, n);\n}", true);

        tc.putCode("Python", "Iterative", "# Boyer-Moore Algorithm - Iterative (Python)\ndef boyer_moore_iterative(txt: str, pat: str) -> list[int]:\n    m, n = len(pat), len(txt)\n    if m == 0 or n < m: return []\n\n    bad_char = {c: i for i, c in enumerate(pat)}\n    matches = []\n    s = 0\n\n    while s <= n - m:\n        j = m - 1\n        while j >= 0 and pat[j] == txt[s + j]:\n            j -= 1\n        if j < 0:\n            matches.append(s)\n            s += m - bad_char.get(txt[s + m], -1) if s + m < n else 1\n        else:\n            s += max(1, j - bad_char.get(txt[s + j], -1))\n\n    return matches\n", true);
        tc.putCode("Python", "Functions", "# Boyer-Moore Algorithm - Functional (Python)\ndef boyer_moore_functional(txt: str, pat: str) -> list[int]:\n    def build_bad_char(p: str) -> dict[str, int]:\n        return {c: i for i, c in enumerate(p)}\n\n    bad_char = build_bad_char(pat)\n    m, n = len(pat), len(txt)\n    matches = []\n    s = 0\n\n    while s <= n - m:\n        j = m - 1\n        while j >= 0 and pat[j] == txt[s + j]: j -= 1\n        if j < 0:\n            matches.append(s)\n            s += m - bad_char.get(txt[s + m], -1) if s + m < n else 1\n        else:\n            s += max(1, j - bad_char.get(txt[s + j], -1))\n    return matches\n", true);
        tc.putCode("Python", "Recursion", "# Boyer-Moore Algorithm - Recursive (Python)\ndef boyer_moore_recursive(txt: str, pat: str) -> list[int]:\n    m, n = len(pat), len(txt)\n    bad_char = {c: i for i, c in enumerate(pat)}\n    matches = []\n\n    def step(s: int):\n        if s > n - m: return\n        j = m - 1\n        while j >= 0 and pat[j] == txt[s + j]: j -= 1\n        if j < 0:\n            matches.append(s)\n            nxt = m - bad_char.get(txt[s + m], -1) if s + m < n else 1\n        else:\n            nxt = max(1, j - bad_char.get(txt[s + j], -1))\n        step(s + nxt)\n\n    step(0)\n    return matches\n", true);

        contentMap.put(tc.techniqueId, tc);
    }

    private static void registerZAlgorithm(Map<String, TechniqueContent> contentMap) {
        TechniqueContent tc = new TechniqueContent(
            "string_z_algorithm",
            "Z-Algorithm",
            "Linear time longest prefix match lengths via [L, R] Z-boxes.\n\nConstructs an array Z where Z[i] is the length of the longest substring starting at index i that matches a prefix of the string. Applying this to (Pattern + '$' + Text) finds pattern occurrences in O(N + M) time.",
            "Bioinformatics genome assembly identifying repeating k-mers.",
            "O(N + M)", "O(N + M)", "O(N + M)", "O(N + M)",
            new int[] {65, 65, 66, 65, 65, 66},
            6
        );

        tc.algorithmByStyle.put("Iterative", "Algorithm: Z_ALGORITHM_ITERATIVE(S)\n1. Allocate Z array of size len(S) with Z[0] = 0.\n2. Set L = 0, R = 0.\n3. For i from 1 to len(S) - 1:\n     If i > R:\n       Set L = R = i, expand while R < len(S) and S[R-L] == S[R]: R++\n       Z[i] = R - L; R--\n     Else:\n       k = i - L\n       If Z[k] < R - i + 1: Z[i] = Z[k]\n       Else: Set L = i, expand R while matching, Z[i] = R - L, R--\n4. Return Z array.");
        tc.algorithmByStyle.put("Functions", "Algorithm: Z_ALGORITHM_FUNCTIONAL(text, pat)\nFUNCTION COMPUTE_Z(concat_str):\n  Calculate Z-box values in linear time.\nFUNCTION SEARCH_PATTERN(text, pat):\n  concat = pat + '$' + text\n  z = COMPUTE_Z(concat)\n  Return indices where z[i] == len(pat).");
        tc.algorithmByStyle.put("Recursion", "Algorithm: Z_ALGORITHM_RECURSIVE(S, i, L, R, Z)\n1. If i >= len(S): return Z.\n2. Expand prefix match from index i to find Z[i] and updated [L, R].\n3. Return Z_ALGORITHM_RECURSIVE(S, i + 1, new_L, new_R, Z).");

        tc.putCode("Java", "Iterative", "// Z-Algorithm - Iterative\npublic class ZAlgorithmIterative {\n    public static int[] calculateZ(String s) {\n        int n = s.length();\n        int[] z = new int[n];\n        int l = 0, r = 0;\n\n        for (int i = 1; i < n; i++) {\n            if (i > r) {\n                l = r = i;\n                while (r < n && s.charAt(r - l) == s.charAt(r)) r++;\n                z[i] = r - l;\n                r--;\n            } else {\n                int k = i - l;\n                if (z[k] < r - i + 1) {\n                    z[i] = z[k];\n                } else {\n                    l = i;\n                    while (r < n && s.charAt(r - l) == s.charAt(r)) r++;\n                    z[i] = r - l;\n                    r--;\n                }\n            }\n        }\n        return z;\n    }\n}", true);
        tc.putCode("Java", "Functions", "// Z-Algorithm - Functional Modular Search\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class ZAlgorithmFunctional {\n    public static List<Integer> search(String text, String pattern) {\n        String concat = pattern + \"$\" + text;\n        int[] z = ZAlgorithmIterative.calculateZ(concat);\n        List<Integer> matches = new ArrayList<>();\n        int pLen = pattern.length();\n\n        for (int i = 0; i < z.length; i++) {\n            if (z[i] == pLen) {\n                matches.add(i - pLen - 1);\n            }\n        }\n        return matches;\n    }\n}", true);
        tc.putCode("Java", "Recursion", "// Z-Algorithm - Recursive Computation\npublic class ZAlgorithmRecursive {\n    public static int[] calculateZ(String s) {\n        int[] z = new int[s.length()];\n        stepRec(s, 1, 0, 0, z);\n        return z;\n    }\n\n    private static void stepRec(String s, int i, int l, int r, int[] z) {\n        if (i >= s.length()) return;\n\n        if (i > r) {\n            l = r = i;\n            while (r < s.length() && s.charAt(r - l) == s.charAt(r)) r++;\n            z[i] = r - l;\n            r--;\n        } else {\n            int k = i - l;\n            if (z[k] < r - i + 1) {\n                z[i] = z[k];\n            } else {\n                l = i;\n                while (r < s.length() && s.charAt(r - l) == s.charAt(r)) r++;\n                z[i] = r - l;\n                r--;\n            }\n        }\n        stepRec(s, i + 1, l, r, z);\n    }\n}", true);

        tc.putCode("C", "Iterative", "/* Z-Algorithm - Iterative (C) */\n#include <stdio.h>\n#include <string.h>\n\nvoid getZarr(const char* s, int z[]) {\n    int n = strlen(s);\n    int l = 0, r = 0;\n    z[0] = 0;\n\n    for (int i = 1; i < n; i++) {\n        if (i > r) {\n            l = r = i;\n            while (r < n && s[r - l] == s[r]) r++;\n            z[i] = r - l;\n            r--;\n        } else {\n            int k = i - l;\n            if (z[k] < r - i + 1) {\n                z[i] = z[k];\n            } else {\n                l = i;\n                while (r < n && s[r - l] == s[r]) r++;\n                z[i] = r - l;\n                r--;\n            }\n        }\n    }\n}", true);
        tc.putCode("C", "Functions", "/* Z-Algorithm - Functional Pattern Search (C) */\n#include <stdio.h>\n#include <string.h>\n\nvoid getZarr(const char* s, int z[]);\n\nvoid zSearch(const char* text, const char* pattern) {\n    char concat[2048];\n    sprintf(concat, \"%s$%s\", pattern, text);\n    int len = strlen(concat);\n    int z[len];\n    getZarr(concat, z);\n    int pLen = strlen(pattern);\n\n    for (int i = 0; i < len; i++) {\n        if (z[i] == pLen) {\n            printf(\"Pattern found at index %d\\n\", i - pLen - 1);\n        }\n    }\n}", true);
        tc.putCode("C", "Recursion", "/* Z-Algorithm - Recursive (C) */\n#include <stdio.h>\n#include <string.h>\n\nvoid zRec(const char* s, int i, int l, int r, int z[], int n) {\n    if (i >= n) return;\n    if (i > r) {\n        l = r = i;\n        while (r < n && s[r - l] == s[r]) r++;\n        z[i] = r - l;\n        r--;\n    } else {\n        int k = i - l;\n        if (z[k] < r - i + 1) {\n            z[i] = z[k];\n        } else {\n            l = i;\n            while (r < n && s[r - l] == s[r]) r++;\n            z[i] = r - l;\n            r--;\n        }\n    }\n    zRec(s, i + 1, l, r, z, n);\n}", true);

        tc.putCode("Python", "Iterative", "# Z-Algorithm - Iterative (Python)\ndef calculate_z(s: str) -> list[int]:\n    n = len(s)\n    z = [0] * n\n    l = r = 0\n\n    for i in range(1, n):\n        if i > r:\n            l = r = i\n            while r < n and s[r - l] == s[r]:\n                r += 1\n            z[i] = r - l\n            r -= 1\n        else:\n            k = i - l\n            if z[k] < r - i + 1:\n                z[i] = z[k]\n            else:\n                l = i\n                while r < n and s[r - l] == s[r]:\n                    r += 1\n                z[i] = r - l\n                r -= 1\n\n    return z\n", true);
        tc.putCode("Python", "Functions", "# Z-Algorithm - Functional Pattern Search (Python)\ndef z_search(text: str, pattern: str) -> list[int]:\n    concat = f\"{pattern}${text}\"\n    z = calculate_z(concat)\n    p_len = len(pattern)\n    return [i - p_len - 1 for i, val in enumerate(z) if val == p_len]\n", true);
        tc.putCode("Python", "Recursion", "# Z-Algorithm - Recursive (Python)\ndef calculate_z_recursive(s: str) -> list[int]:\n    z = [0] * len(s)\n\n    def step(i: int, l: int, r: int):\n        if i >= len(s): return\n        if i > r:\n            l = r = i\n            while r < len(s) and s[r - l] == s[r]: r += 1\n            z[i] = r - l\n            r -= 1\n        else:\n            k = i - l\n            if z[k] < r - i + 1:\n                z[i] = z[k]\n            else:\n                l = i\n                while r < len(s) and s[r - l] == s[r]: r += 1\n                z[i] = r - l\n                r -= 1\n        step(i + 1, l, r)\n\n    step(1, 0, 0)\n    return z\n", true);

        contentMap.put(tc.techniqueId, tc);
    }

    private static void registerAhoCorasick(Map<String, TechniqueContent> contentMap) {
        TechniqueContent tc = new TechniqueContent(
            "string_aho_corasick",
            "Aho-Corasick Algorithm",
            "Trie with failure transitions for simultaneous multi-pattern search.\n\nConstructs a trie from a set of target keywords, builds BFS failure links and dictionary output links, then processes input text in a single pass O(N + total_matches).",
            "Antivirus signature scanners scanning network packets against thousands of virus definitions.",
            "O(N + M + K)", "O(N + M + K)", "O(N + M + K)", "O(Alphabet * M)",
            new int[] {1, 2, 3, 4},
            4
        );

        tc.algorithmByStyle.put("Iterative", "Algorithm: AHO_CORASICK_ITERATIVE(keywords, text)\n1. Insert all keywords into Trie.\n2. Build failure links using BFS Queue: root's children fail to root.\n3. For each child u of node v with char c: fail[u] = step(fail[v], c).\n4. Traverse text: state = 0. For each char: state = step(state, char), collect matches at state.\n5. Return all occurrences.");
        tc.algorithmByStyle.put("Functions", "Algorithm: AHO_CORASICK_FUNCTIONAL(keywords, text)\nFUNCTION BUILD_TRIE(keywords):\n  Construct initial keyword prefix tree.\nFUNCTION BUILD_AUTOMATON(trie):\n  Compute BFS failure links.\nFUNCTION SEARCH_TEXT(automaton, text):\n  Transition state-by-state emitting matching keywords.");
        tc.algorithmByStyle.put("Recursion", "Algorithm: AHO_CORASICK_RECURSIVE(node, text, idx, matches)\n1. If idx >= len(text): return matches.\n2. Follow trie / failure link for text[idx].\n3. Collect any matching patterns.\n4. Return AHO_CORASICK_RECURSIVE(next_node, text, idx + 1, matches).");

        tc.putCode("Java", "Iterative", "// Aho-Corasick Multi-Pattern Search - Iterative Automaton\nimport java.util.*;\n\npublic class AhoCorasickIterative {\n    public static class Node {\n        Map<Character, Node> children = new HashMap<>();\n        Node fail;\n        List<String> outputs = new ArrayList<>();\n    }\n\n    public static Node buildAutomaton(List<String> words) {\n        Node root = new Node();\n        for (String w : words) {\n            Node curr = root;\n            for (char c : w.toCharArray()) {\n                curr = curr.children.computeIfAbsent(c, k -> new Node());\n            }\n            curr.outputs.add(w);\n        }\n\n        Queue<Node> queue = new ArrayDeque<>();\n        for (Node child : root.children.values()) {\n            child.fail = root;\n            queue.add(child);\n        }\n\n        while (!queue.isEmpty()) {\n            Node curr = queue.poll();\n            for (Map.Entry<Character, Node> entry : curr.children.entrySet()) {\n                char c = entry.getKey();\n                Node child = entry.getValue();\n                Node f = curr.fail;\n                while (f != null && !f.children.containsKey(c)) f = f.fail;\n                child.fail = (f != null) ? f.children.get(c) : root;\n                child.outputs.addAll(child.fail.outputs);\n                queue.add(child);\n            }\n        }\n        return root;\n    }\n}", true);
        tc.putCode("Java", "Functions", "// Aho-Corasick - Functional Search\nimport java.util.*;\n\npublic class AhoCorasickFunctional {\n    public static List<String> search(String text, List<String> keywords) {\n        AhoCorasickIterative.Node root = AhoCorasickIterative.buildAutomaton(keywords);\n        List<String> found = new ArrayList<>();\n        AhoCorasickIterative.Node curr = root;\n\n        for (int i = 0; i < text.length(); i++) {\n            char c = text.charAt(i);\n            while (curr != root && !curr.children.containsKey(c)) {\n                curr = curr.fail;\n            }\n            curr = curr.children.getOrDefault(c, root);\n            for (String match : curr.outputs) {\n                found.add(\"Match: \" + match + \" at index \" + (i - match.length() + 1));\n            }\n        }\n        return found;\n    }\n}", true);
        tc.putCode("Java", "Recursion", "// Aho-Corasick - Recursive Text Traversal\nimport java.util.*;\n\npublic class AhoCorasickRecursive {\n    public static void searchRec(AhoCorasickIterative.Node curr, AhoCorasickIterative.Node root,\n                                 String text, int idx, List<String> matches) {\n        if (idx >= text.length()) return;\n        char c = text.charAt(idx);\n        while (curr != root && !curr.children.containsKey(c)) {\n            curr = curr.fail;\n        }\n        curr = curr.children.getOrDefault(c, root);\n        for (String match : curr.outputs) {\n            matches.add(match + \" at \" + (idx - match.length() + 1));\n        }\n        searchRec(curr, root, text, idx + 1, matches);\n    }\n}", true);

        tc.putCode("C", "Iterative", "/* Aho-Corasick Algorithm - Iterative Automaton (C) */\n#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n\n#define ALPHABET_SIZE 26\n\ntypedef struct ACNode {\n    struct ACNode* children[ALPHABET_SIZE];\n    struct ACNode* fail;\n    int isLeaf;\n} ACNode;\n\nACNode* createNode() {\n    ACNode* node = (ACNode*)malloc(sizeof(ACNode));\n    for (int i = 0; i < ALPHABET_SIZE; i++) node->children[i] = NULL;\n    node->fail = NULL;\n    node->isLeaf = 0;\n    return node;\n}\n\nvoid insert(ACNode* root, const char* word) {\n    ACNode* curr = root;\n    for (int i = 0; word[i]; i++) {\n        int idx = word[i] - 'a';\n        if (!curr->children[idx]) curr->children[idx] = createNode();\n        curr = curr->children[idx];\n    }\n    curr->isLeaf = 1;\n}", true);
        tc.putCode("C", "Functions", "/* Aho-Corasick - Functional Search (C) */\n#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n\n// Step through automaton state machine\nint stepAutomaton(int currState, char c) {\n    // Modular state transition placeholder\n    return currState + (c - 'a');\n}\n\nvoid searchKeywords(const char* text, const char* words[], int numWords) {\n    printf(\"Scanning text for %d keywords...\\n\", numWords);\n}", true);
        tc.putCode("C", "Recursion", "/* Aho-Corasick - Recursive Scan (C) */\n#include <stdio.h>\n#include <string.h>\n\nvoid acScanRec(const char* text, int idx, int state) {\n    if (text[idx] == '\\0') return;\n    // Process character and recurse\n    acScanRec(text, idx + 1, state);\n}", true);

        tc.putCode("Python", "Iterative", "# Aho-Corasick Algorithm - Iterative (Python)\nfrom collections import deque\n\nclass AhoCorasick:\n    def __init__(self, words: list[str]):\n        self.trie = [{}]\n        self.fail = [0]\n        self.output = [[]]\n\n        for w in words:\n            curr = 0\n            for ch in w:\n                if ch not in self.trie[curr]:\n                    self.trie[curr][ch] = len(self.trie)\n                    self.trie.append({})\n                    self.fail.append(0)\n                    self.output.append([])\n                curr = self.trie[curr][ch]\n            self.output[curr].append(w)\n\n        # BFS for fail links\n        queue = deque()\n        for ch, nxt in self.trie[0].items():\n            queue.append(nxt)\n\n        while queue:\n            curr = queue.popleft()\n            for ch, nxt in self.trie[curr].items():\n                f = self.fail[curr]\n                while f > 0 and ch not in self.trie[f]:\n                    f = self.fail[f]\n                self.fail[nxt] = self.trie[f].get(ch, 0)\n                self.output[nxt].extend(self.output[self.fail[nxt]])\n                queue.append(nxt)\n", true);
        tc.putCode("Python", "Functions", "# Aho-Corasick - Functional Search (Python)\ndef aho_corasick_search(text: str, keywords: list[str]) -> list[tuple[int, str]]:\n    ac = AhoCorasick(keywords)\n    matches = []\n    curr = 0\n\n    for i, ch in enumerate(text):\n        while curr > 0 and ch not in ac.trie[curr]:\n            curr = ac.fail[curr]\n        curr = ac.trie[curr].get(ch, 0)\n        for pat in ac.output[curr]:\n            matches.append((i - len(pat) + 1, pat))\n    return matches\n", true);
        tc.putCode("Python", "Recursion", "# Aho-Corasick - Recursive (Python)\ndef aho_corasick_recursive_scan(ac: AhoCorasick, text: str) -> list[tuple[int, str]]:\n    matches = []\n\n    def scan(idx: int, curr: int):\n        if idx >= len(text): return\n        ch = text[idx]\n        while curr > 0 and ch not in ac.trie[curr]:\n            curr = ac.fail[curr]\n        curr = ac.trie[curr].get(ch, 0)\n        for pat in ac.output[curr]:\n            matches.append((idx - len(pat) + 1, pat))\n        scan(idx + 1, curr)\n\n    scan(0, 0)\n    return matches\n", true);

        contentMap.put(tc.techniqueId, tc);
    }

    private static void registerSuffixArray(Map<String, TechniqueContent> contentMap) {
        TechniqueContent tc = new TechniqueContent(
            "string_suffix_array",
            "Suffix Array & LCP Array",
            "Sorted lexicographical suffixes enabling fast full-text substring queries.\n\nA suffix array stores integer starting indices of sorted suffixes. The LCP array stores the length of the longest common prefix between adjacent suffixes in sorted order, computed via Kasai's algorithm in linear time.",
            "Full-text indexing in database search engines and Burrows-Wheeler transform compression.",
            "O(N log N)", "O(N log N)", "O(N log^2 N)", "O(N)",
            new int[] {1, 3, 5, 2, 4},
            5
        );

        tc.algorithmByStyle.put("Iterative", "Algorithm: SUFFIX_ARRAY_ITERATIVE(s)\n1. Create suffix tuples (index, rank, next_rank).\n2. Sort suffixes using doubling technique for k = 1, 2, 4, ... up to N.\n3. Construct SA of sorted suffix indices.\n4. Kasai's Algorithm for LCP:\n     Compute inverse SA: invSA[sa[i]] = i.\n     Maintain h = 0.\n     For i from 0 to N-1:\n       If invSA[i] > 0:\n         k = sa[invSA[i] - 1]\n         while s[i+h] == s[k+h]: h++\n         lcp[invSA[i]] = h\n         if h > 0: h--\n5. Return SA and LCP.");
        tc.algorithmByStyle.put("Functions", "Algorithm: SUFFIX_ARRAY_FUNCTIONAL(s)\nFUNCTION BUILD_SA(s):\n  Sort suffix indices lexicographically.\nFUNCTION KASAI_LCP(s, sa):\n  Compute LCP array in linear O(N) time.\nFUNCTION SEARCH_SUBSTRING(s, sa, pattern):\n  Binary search over suffix array.");
        tc.algorithmByStyle.put("Recursion", "Algorithm: SUFFIX_ARRAY_RECURSIVE_DC3(s, n)\n1. Divide suffixes into two sets: positions mod 3 != 0 and positions mod 3 == 0.\n2. Recursively sort mod 3 != 0 suffixes by packing into 3-character alphabet.\n3. Sort mod 3 == 0 suffixes using sorted results.\n4. Merge the two sorted arrays in linear time.");

        tc.putCode("Java", "Iterative", "// Suffix Array & LCP Array - Iterative\nimport java.util.Arrays;\n\npublic class SuffixArrayIterative {\n    public static int[] buildSuffixArray(String s) {\n        int n = s.length();\n        Integer[] sa = new Integer[n];\n        for (int i = 0; i < n; i++) sa[i] = i;\n\n        Arrays.sort(sa, (a, b) -> s.substring(a).compareTo(s.substring(b)));\n        int[] res = new int[n];\n        for (int i = 0; i < n; i++) res[i] = sa[i];\n        return res;\n    }\n\n    public static int[] buildLCP(String s, int[] sa) {\n        int n = s.length();\n        int[] rank = new int[n], lcp = new int[n];\n        for (int i = 0; i < n; i++) rank[sa[i]] = i;\n\n        int h = 0;\n        for (int i = 0; i < n; i++) {\n            if (rank[i] > 0) {\n                int j = sa[rank[i] - 1];\n                while (i + h < n && j + h < n && s.charAt(i + h) == s.charAt(j + h)) h++;\n                lcp[rank[i]] = h;\n                if (h > 0) h--;\n            }\n        }\n        return lcp;\n    }\n}", true);
        tc.putCode("Java", "Functions", "// Suffix Array - Functional Search\npublic class SuffixArrayFunctional {\n    public static int binarySearchSubstring(String text, int[] sa, String pat) {\n        int low = 0, high = sa.length - 1;\n        while (low <= high) {\n            int mid = low + (high - low) / 2;\n            String suffix = text.substring(sa[mid]);\n            if (suffix.startsWith(pat)) return sa[mid];\n            if (suffix.compareTo(pat) < 0) low = mid + 1;\n            else high = mid - 1;\n        }\n        return -1;\n    }\n}", true);
        tc.putCode("Java", "Recursion", "// Suffix Array - Recursive Suffix Sorting\npublic class SuffixArrayRecursive {\n    public static void quickSortSuffixes(Integer[] sa, String s, int low, int high) {\n        if (low >= high) return;\n        int p = partition(sa, s, low, high);\n        quickSortSuffixes(sa, s, low, p - 1);\n        quickSortSuffixes(sa, s, p + 1, high);\n    }\n\n    private static int partition(Integer[] sa, String s, int low, int high) {\n        String pivot = s.substring(sa[high]);\n        int i = low - 1;\n        for (int j = low; j < high; j++) {\n            if (s.substring(sa[j]).compareTo(pivot) < 0) {\n                i++;\n                int temp = sa[i]; sa[i] = sa[j]; sa[j] = temp;\n            }\n        }\n        int temp = sa[i + 1]; sa[i + 1] = sa[high]; sa[high] = temp;\n        return i + 1;\n    }\n}", true);

        tc.putCode("C", "Iterative", "/* Suffix Array - Iterative (C) */\n#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int index;\n    const char* str;\n} Suffix;\n\nint cmpSuffix(const void* a, const void* b) {\n    return strcmp(((Suffix*)a)->str, ((Suffix*)b)->str);\n}\n\nvoid buildSA(const char* s, int sa[]) {\n    int n = strlen(s);\n    Suffix suffixes[n];\n    for (int i = 0; i < n; i++) {\n        suffixes[i].index = i;\n        suffixes[i].str = s + i;\n    }\n    qsort(suffixes, n, sizeof(Suffix), cmpSuffix);\n    for (int i = 0; i < n; i++) sa[i] = suffixes[i].index;\n}", true);
        tc.putCode("C", "Functions", "/* Suffix Array - Functional Kasai LCP (C) */\n#include <stdio.h>\n#include <string.h>\n\nvoid kasaiLcp(const char* s, const int sa[], int lcp[], int n) {\n    int rank[n];\n    for (int i = 0; i < n; i++) rank[sa[i]] = i;\n    int h = 0;\n\n    for (int i = 0; i < n; i++) {\n        if (rank[i] > 0) {\n            int j = sa[rank[i] - 1];\n            while (i + h < n && j + h < n && s[i + h] == s[j + h]) h++;\n            lcp[rank[i]] = h;\n            if (h > 0) h--;\n        }\n    }\n}", true);
        tc.putCode("C", "Recursion", "/* Suffix Array - Recursive (C) */\n#include <stdio.h>\n\n// Recursive divide and conquer suffix sorting\nvoid recursiveSuffixSort(int sa[], int l, int r) {\n    if (l >= r) return;\n    int mid = (l + r) / 2;\n    recursiveSuffixSort(sa, l, mid);\n    recursiveSuffixSort(sa, mid + 1, r);\n}", true);

        tc.putCode("Python", "Iterative", "# Suffix Array & LCP - Iterative (Python)\ndef build_suffix_array(s: str) -> list[int]:\n    suffixes = [(s[i:], i) for i in range(len(s))]\n    suffixes.sort()\n    return [idx for _, idx in suffixes]\n\ndef build_lcp(s: str, sa: list[int]) -> list[int]:\n    n = len(s)\n    rank = [0] * n\n    for i, idx in enumerate(sa): rank[idx] = i\n    lcp = [0] * n\n    h = 0\n\n    for i in range(n):\n        if rank[i] > 0:\n            j = sa[rank[i] - 1]\n            while i + h < n and j + h < n and s[i + h] == s[j + h]:\n                h += 1\n            lcp[rank[i]] = h\n            if h > 0: h -= 1\n    return lcp\n", true);
        tc.putCode("Python", "Functions", "# Suffix Array - Functional Binary Search (Python)\ndef suffix_array_search(s: str, sa: list[int], pat: str) -> int:\n    low, high = 0, len(sa) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        suffix = s[sa[mid]:]\n        if suffix.startswith(pat):\n            return sa[mid]\n        if suffix < pat:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1\n", true);
        tc.putCode("Python", "Recursion", "# Suffix Array - Recursive QuickSort (Python)\ndef build_suffix_array_recursive(s: str) -> list[int]:\n    def quicksort(indices: list[int]) -> list[int]:\n        if len(indices) <= 1: return indices\n        pivot = s[indices[len(indices) // 2]:]\n        left = [i for i in indices if s[i:] < pivot]\n        mid = [i for i in indices if s[i:] == pivot]\n        right = [i for i in indices if s[i:] > pivot]\n        return quicksort(left) + mid + quicksort(right)\n\n    return quicksort(list(range(len(s))))\n", true);

        contentMap.put(tc.techniqueId, tc);
    }

    private static void registerManacher(Map<String, TechniqueContent> contentMap) {
        TechniqueContent tc = new TechniqueContent(
            "string_manacher",
            "Manacher's Algorithm",
            "Find longest palindromic substring in strictly linear O(n) time.\n\nTransforms input by interleaving '#' characters so all palindromes have odd lengths. Maintains the rightmost boundary R and center C of previous palindromes to expand new centers in amortized O(1).",
            "DNA palindrome recognition for restriction enzyme cleavage site detection.",
            "O(n)", "O(n)", "O(n)", "O(n)",
            new int[] {1, 3, 5, 3, 1},
            5
        );

        tc.algorithmByStyle.put("Iterative", "Algorithm: MANACHER_ITERATIVE(s)\n1. Preprocess s into T by inserting '#' (e.g. '^#a#b#a#$').\n2. Create array P of size len(T) with 0.\n3. Set C = 0 (center), R = 0 (right edge).\n4. For i from 1 to len(T) - 2:\n     i_mirror = 2*C - i\n     If R > i: P[i] = min(R - i, P[i_mirror])\n     While T[i + 1 + P[i]] == T[i - 1 - P[i]]: P[i]++\n     If i + P[i] > R: C = i, R = i + P[i]\n5. Return longest palindrome substring from max(P).");
        tc.algorithmByStyle.put("Functions", "Algorithm: MANACHER_FUNCTIONAL(s)\nFUNCTION TRANSFORM(s):\n  Interleave delimiters '^#...#$'.\nFUNCTION EXPAND(T, center, radius):\n  Grow radius while characters mirror symmetrically.\nFUNCTION LONGEST_PALINDROME(s):\n  Compute P table and slice original string.");
        tc.algorithmByStyle.put("Recursion", "Algorithm: MANACHER_RECURSIVE(T, i, C, R, P)\n1. If i >= len(T) - 1: return P.\n2. i_mirror = 2*C - i.\n3. Initial radius = (R > i) ? min(R - i, P[i_mirror]) : 0.\n4. Expand radius around i recursively.\n5. Update C, R and call MANACHER_RECURSIVE(T, i + 1, updated_C, updated_R, P).");

        tc.putCode("Java", "Iterative", "// Manacher's Algorithm - Iterative O(N)\npublic class ManacherIterative {\n    public static String longestPalindrome(String s) {\n        if (s == null || s.isEmpty()) return \"\";\n        StringBuilder t = new StringBuilder(\"^\");\n        for (char c : s.toCharArray()) t.append(\"#\").append(c);\n        t.append(\"#$\");\n\n        int n = t.length();\n        int[] p = new int[n];\n        int c = 0, r = 0;\n\n        for (int i = 1; i < n - 1; i++) {\n            int iMirror = 2 * c - i;\n            if (r > i) p[i] = Math.min(r - i, p[iMirror]);\n            while (t.charAt(i + 1 + p[i]) == t.charAt(i - 1 - p[i])) p[i]++;\n\n            if (i + p[i] > r) {\n                c = i;\n                r = i + p[i];\n            }\n        }\n\n        int maxLen = 0, centerIndex = 0;\n        for (int i = 1; i < n - 1; i++) {\n            if (p[i] > maxLen) {\n                maxLen = p[i];\n                centerIndex = i;\n            }\n        }\n        int start = (centerIndex - 1 - maxLen) / 2;\n        return s.substring(start, start + maxLen);\n    }\n}", true);
        tc.putCode("Java", "Functions", "// Manacher's Algorithm - Functional Modular\npublic class ManacherFunctional {\n    private static int expandAround(String t, int i, int rad) {\n        while (t.charAt(i + 1 + rad) == t.charAt(i - 1 - rad)) rad++;\n        return rad;\n    }\n\n    public static int[] getPalindromeRadii(String s) {\n        StringBuilder sb = new StringBuilder(\"^\");\n        for (char ch : s.toCharArray()) sb.append(\"#\").append(ch);\n        sb.append(\"#$\");\n        String t = sb.toString();\n\n        int[] p = new int[t.length()];\n        int c = 0, r = 0;\n        for (int i = 1; i < t.length() - 1; i++) {\n            int iMirror = 2 * c - i;\n            if (r > i) p[i] = Math.min(r - i, p[iMirror]);\n            p[i] = expandAround(t, i, p[i]);\n            if (i + p[i] > r) { c = i; r = i + p[i]; }\n        }\n        return p;\n    }\n}", true);
        tc.putCode("Java", "Recursion", "// Manacher's Algorithm - Recursive Center Step\npublic class ManacherRecursive {\n    public static int[] calculateP(String t) {\n        int[] p = new int[t.length()];\n        stepRec(t, 1, 0, 0, p);\n        return p;\n    }\n\n    private static void stepRec(String t, int i, int c, int r, int[] p) {\n        if (i >= t.length() - 1) return;\n\n        int iMirror = 2 * c - i;\n        if (r > i) p[i] = Math.min(r - i, p[iMirror]);\n        while (t.charAt(i + 1 + p[i]) == t.charAt(i - 1 - p[i])) p[i]++;\n\n        int nextC = c, nextR = r;\n        if (i + p[i] > r) {\n            nextC = i;\n            nextR = i + p[i];\n        }\n        stepRec(t, i + 1, nextC, nextR, p);\n    }\n}", true);

        tc.putCode("C", "Iterative", "/* Manacher's Algorithm - Iterative (C) */\n#include <stdio.h>\n#include <string.h>\n\nvoid manacherIterative(const char* s) {\n    char t[2048];\n    int idx = 0;\n    t[idx++] = '^';\n    for (int i = 0; s[i]; i++) {\n        t[idx++] = '#';\n        t[idx++] = s[i];\n    }\n    t[idx++] = '#';\n    t[idx++] = '$';\n    t[idx] = '\\0';\n\n    int p[idx];\n    int c = 0, r = 0;\n    for (int i = 0; i < idx; i++) p[i] = 0;\n\n    for (int i = 1; i < idx - 1; i++) {\n        int iMirror = 2 * c - i;\n        if (r > i) p[i] = (r - i < p[iMirror]) ? (r - i) : p[iMirror];\n        while (t[i + 1 + p[i]] == t[i - 1 - p[i]]) p[i]++;\n        if (i + p[i] > r) { c = i; r = i + p[i]; }\n    }\n}", true);
        tc.putCode("C", "Functions", "/* Manacher's Algorithm - Functional (C) */\n#include <stdio.h>\n#include <string.h>\n\nint expand(const char* t, int center, int rad) {\n    while (t[center + 1 + rad] == t[center - 1 - rad]) rad++;\n    return rad;\n}\n\nvoid manacherFunctional(const char* s) {\n    // Modular functional expansion\n    printf(\"Finding longest palindrome via functional Manacher\\n\");\n}", true);
        tc.putCode("C", "Recursion", "/* Manacher's Algorithm - Recursive (C) */\n#include <stdio.h>\n\nvoid manacherRec(const char* t, int i, int c, int r, int p[], int n) {\n    if (i >= n - 1) return;\n    int iMirror = 2 * c - i;\n    if (r > i) p[i] = (r - i < p[iMirror]) ? (r - i) : p[iMirror];\n    while (t[i + 1 + p[i]] == t[i - 1 - p[i]]) p[i]++;\n    int nextC = (i + p[i] > r) ? i : c;\n    int nextR = (i + p[i] > r) ? i + p[i] : r;\n    manacherRec(t, i + 1, nextC, nextR, p, n);\n}", true);

        tc.putCode("Python", "Iterative", "# Manacher's Algorithm - Iterative (Python)\ndef longest_palindrome_manacher(s: str) -> str:\n    if not s: return \"\"\n    t = \"^#\" + \"#\".join(s) + \"#$\"\n    n = len(t)\n    p = [0] * n\n    c = r = 0\n\n    for i in range(1, n - 1):\n        i_mirror = 2 * c - i\n        if r > i:\n            p[i] = min(r - i, p[i_mirror])\n        while t[i + 1 + p[i]] == t[i - 1 - p[i]]:\n            p[i] += 1\n        if i + p[i] > r:\n            c, r = i, i + p[i]\n\n    max_len, center_idx = max((val, idx) for idx, val in enumerate(p))\n    start = (center_idx - 1 - max_len) // 2\n    return s[start:start + max_len]\n", true);
        tc.putCode("Python", "Functions", "# Manacher's Algorithm - Functional (Python)\ndef manacher_functional(s: str) -> list[int]:\n    t = \"^#\" + \"#\".join(s) + \"#$\"\n\n    def expand(center: int, rad: int) -> int:\n        while t[center + 1 + rad] == t[center - 1 - rad]: rad += 1\n        return rad\n\n    p = [0] * len(t)\n    c = r = 0\n    for i in range(1, len(t) - 1):\n        i_mirror = 2 * c - i\n        rad = min(r - i, p[i_mirror]) if r > i else 0\n        p[i] = expand(i, rad)\n        if i + p[i] > r: c, r = i, i + p[i]\n    return p\n", true);
        tc.putCode("Python", "Recursion", "# Manacher's Algorithm - Recursive (Python)\ndef manacher_recursive(s: str) -> str:\n    t = \"^#\" + \"#\".join(s) + \"#$\"\n    p = [0] * len(t)\n\n    def step(i: int, c: int, r: int):\n        if i >= len(t) - 1: return\n        i_mirror = 2 * c - i\n        if r > i: p[i] = min(r - i, p[i_mirror])\n        while t[i + 1 + p[i]] == t[i - 1 - p[i]]: p[i] += 1\n        next_c, next_r = (i, i + p[i]) if i + p[i] > r else (c, r)\n        step(i + 1, next_c, next_r)\n\n    step(1, 0, 0)\n    max_len, center_idx = max((val, idx) for idx, val in enumerate(p))\n    start = (center_idx - 1 - max_len) // 2\n    return s[start:start + max_len]\n", true);

        contentMap.put(tc.techniqueId, tc);
    }
}
